import * as React from 'react'

import {useIsHintsModeEnabled} from './Hints.hooks'
import {isObligatoryHintsModeEnabled} from './Hints.settings'
import Board from './HintsBoard/HintsBoard'
import ObligatoryHintsController from './ObligatoryHintsController/ObligatoryHintsController'

const INITIAL_RENDER_DELAY = 2000

function Hints() {
  const [ready, setReady] = React.useState(false)
  const {isEnabled, isGuestOrRoot} = useIsHintsModeEnabled()

  React.useEffect(() => {
    const timer = setTimeout(() => setReady(true), INITIAL_RENDER_DELAY)
    return () => clearTimeout(timer)
  }, [])

  if (isGuestOrRoot || !ready) {
    return null
  }

  return isEnabled ? <Board /> : isObligatoryHintsModeEnabled ? <ObligatoryHintsController /> : null
}

export default Hints
