import Tab from '@jetbrains/ring-ui-built/components/tabs/tab'
import {Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import * as React from 'react'

import Hint from '../../HintPopup/HintPopup'
import {useHintData} from '../../Hints.hooks'
import {HINT_CATEGORY, stringifyHintId} from '../../Hints.types'

import HintsLink from './HintsLink/HintsLink'
import HintsPager from './HintsPager/HintsPager'

import styles from './HintsList.module.css'

import {isValue} from 'src/utils/guards'

function HintsList() {
  const {
    onSelectNext,
    onSelectPrevious,
    onSelectCategory,
    registeredCategories,
    currentCategoryHints,
    selectedHints,
  } = useHintData()
  const paginationCaption = React.useMemo(() => {
    if (currentCategoryHints.category == null) {
      return ''
    }

    return `Page ${registeredCategories.indexOf(currentCategoryHints.category) + 1} of ${
      registeredCategories.length
    }`
  }, [registeredCategories, currentCategoryHints.category])
  const tabsContent = React.useMemo(
    () => (
      <div className={styles.tipsContainer}>
        {currentCategoryHints.collection.map(hint => (
          <HintsLink key={stringifyHintId(hint.id)} hint={hint} />
        ))}
      </div>
    ),
    [currentCategoryHints.collection],
  )
  const tabs = React.useMemo(
    () =>
      [...registeredCategories].map((item, index) => (
        <Tab
          key={item}
          title={`${item}${index === 0 ? ' Hints' : ''}`}
          id={item}
          className={styles.category}
          activeClassName={styles.categorySelected}
          collapsedClassName={styles.categoryCollapsed}
        >
          {tabsContent}
        </Tab>
      )),
    [registeredCategories, tabsContent],
  )
  const renderedHints = React.useMemo(
    () => selectedHints.map(hintId => <Hint key={stringifyHintId(hintId)} id={hintId} />),
    [selectedHints],
  )

  const handleSelectCategory = React.useCallback(
    (category: string) => {
      if (isValue(HINT_CATEGORY, category)) {
        onSelectCategory(category)
      }
    },
    [onSelectCategory],
  )

  if (registeredCategories.length === 0) {
    return null
  }

  return (
    <div className={styles.panel} data-test="hint-container">
      <Tabs
        selected={currentCategoryHints.category ?? undefined}
        onSelect={handleSelectCategory}
        morePopupClassName={styles.popup}
        moreClassName={styles.category}
        autoCollapse
        initialVisibleItems={2}
      >
        {tabs}
      </Tabs>
      {registeredCategories.length > 1 ? (
        <HintsPager
          paginationCaption={paginationCaption}
          next={onSelectNext}
          previous={onSelectPrevious}
        />
      ) : null}
      {renderedHints}
    </div>
  )
}

export default React.memo(HintsList)
