import Button from '@jetbrains/ring-ui-built/components/button/button'
import * as React from 'react'

import styles from './HintsPager.module.css'

type Props = {
  next: () => unknown
  previous: () => unknown
  paginationCaption: string
}

function HintsPager({next, previous, paginationCaption}: Props) {
  return (
    <div className={styles.pagination}>
      <span className={styles.pages}>{paginationCaption}</span>
      <div>
        <Button className={styles.controlButton} onClick={previous}>
          {'Previous'}
        </Button>
        <Button className={styles.controlButton} onClick={next}>
          {'Next hints'}
        </Button>
      </div>
    </div>
  )
}

export default React.memo(HintsPager)
