import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import * as React from 'react'

import {useSetUserProperty} from '../../../../hooks/useSetUserProperty'

import HintsList from './HintsList/HintsList'
import BackroundImage from './tips-background.svg'

import styles from './HintsBoard.module.css'

import ServiceMessage from 'src/components/common/ServiceMessage/ServiceMessage'
import {UserProperties} from 'src/utils/userProperties'

function HintsBoard() {
  const setUserProperty = useSetUserProperty()
  const closePopup = React.useCallback(
    () => setUserProperty(UserProperties.TIPS_MODE, 'false'),
    [setUserProperty],
  )

  return (
    <ServiceMessage
      onCloseRequest={closePopup}
      containerClassName={styles.containerClassName}
      captionClassName={styles.captionClassName}
      descriptionClassName={styles.descriptionClassName}
      closeButtonClassName={styles.closeButtonClassName}
      theme={Theme.LIGHT}
    >
      <HintsList />
      <BackroundImage className={styles.background} />
    </ServiceMessage>
  )
}

export default React.memo(HintsBoard)
