import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import * as React from 'react'

import {hideHint, showHint} from '../../../Hints.actions'
import type {Hint} from '../../../Hints.types'

import styles from './HintsLink.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

type OwnProps = {
  hint: Hint
}

function HintsLink({hint}: OwnProps) {
  const {helpLink} = hint
  const dispatch = useAppDispatch()
  const hoverStart = React.useCallback(() => {
    dispatch(showHint(hint.id))
  }, [dispatch, hint.id])
  const hoverEnd = React.useCallback(() => {
    dispatch(hideHint(hint.id))
  }, [dispatch, hint.id])
  return (
    <ButtonGroup
      split
      className={styles.tip}
      onFocusCapture={hoverStart}
      onMouseEnter={hoverStart}
      onMouseLeave={hoverEnd}
      onBlur={hoverEnd}
    >
      <Button className={styles.tipName}>{hint.name}</Button>
      {helpLink != null && (
        <Button
          className={styles.readMore}
          title={'Open related article in TeamCity Documentation'}
          href={helpLink}
          target={'_blank'}
          rel={'noreferrer'}
        >
          <SvgIcon className={styles.readMoreIcon} icon={'new-window'} />
        </Button>
      )}
    </ButtonGroup>
  )
}

export default React.memo(HintsLink)
